#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    string w[5] = {"b", "a", "b", "c", "b"};
    map<string, int> freq;
    for (int i = 0; i < 5; i++) freq[w[i]]++;
    for (auto& [k, n] : freq) cout << k << n << " ";
    cout << endl;
    return 0;
}

